const fs = require('fs');

for (const file of ['README.md', 'notes.txt']) {
  const text = fs.readFileSync(file, 'utf8');
  // Count lines: number of newline-terminated lines, plus a trailing
  // partial line if the file doesn't end with a newline.
  const newlines = (text.match(/\n/g) || []).length;
  const count = text.length === 0 ? 0 : newlines + (text.endsWith('\n') ? 0 : 1);
  console.log(`${file}: ${count} lines`);
}

